"""Self-contained evidence viewer; point support is never painted as free space."""
import json, sqlite3, shutil
from pathlib import Path
import numpy as np
from PIL import Image, ImageDraw

def render(c,rows,out,predroot):
 db=sqlite3.connect(out/'runtime/map.sqlite');nodes=[{**json.loads(a),'id':i,'kind':k} for i,k,a in db.execute('SELECT * FROM nodes')];edges=[dict(source=a,target=b,kind=k,**json.loads(x)) for a,b,k,x in db.execute('SELECT * FROM edges')];defaults=dict(db.execute("SELECT key,value FROM metadata"));db.close()
 defaults=json.loads(defaults.get('object_defaults','{}'))
 for n in nodes:
  if n['kind']=='object':
   for k,v in defaults.items():n.setdefault(k,v)
 for n in nodes:
  if n['kind']=='object' and 'observations' not in n:n['observations']=[{k:v for k,v in e.items() if k not in ('source','target','kind')} for e in edges if e['target']==n['id'] and e['kind']=='observes']
 nodes=[n for n in nodes if n['kind'] not in ('scene','floor')]
 visible_ids={n['id'] for n in nodes};edges=[e for e in edges if e['source'] in visible_ids and e['target'] in visible_ids]
 points=np.load(out/'baseline/points.npy');points=points[::max(1,len(points)//12000)]
 gallery=out/'audit/images';gallery.mkdir(exist_ok=True)
 for r in rows:
  f=predroot/'images'/f'{r["frame_id"]}.jpg'
  if f.exists():shutil.copyfile(f,gallery/f.name)
 data=dict(nodes=nodes,edges=edges,points=points[:,[0,2]].round(2).tolist(),report=json.loads((out/'report.json').read_text()),frames=rows,config=dict(scene=c['scene'],calibration=c['calibration_status'],image_size=c['image_size']))
 page='''<!doctype html><html lang="zh"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>停车场指标 1.2 分层认知地图</title><style>
*{box-sizing:border-box}body{margin:0;background:#eef2f6;color:#182c3e;font:15px system-ui}header{background:#142c40;color:white;padding:24px 32px}h1{margin:0 0 8px;font-size:26px}.meta{color:#a7c5d9}main{padding:20px;max-width:1700px;margin:auto}.metrics{display:flex;gap:12px;flex-wrap:wrap}.card{background:white;border:1px solid #d2dde5;border-radius:10px;padding:16px;margin-bottom:16px}.metrics .card{flex:1;min-width:160px}.big{font-size:26px;font-weight:650}.grid{display:grid;grid-template-columns:1.5fr 1fr;gap:16px}svg{width:100%;background:#edf0f3;border-radius:8px}#map{height:560px}#hierarchy{height:300px}label{margin-right:12px;font-size:13px}input,select,button{padding:6px}pre{white-space:pre-wrap;max-height:380px;overflow:auto;font:12px monospace}.warn{color:#9d5110}.legend{line-height:2;color:#4c6273}img{width:100%;max-height:400px;object-fit:contain}#detail{font-size:13px}circle{cursor:pointer}table{border-collapse:collapse;width:100%;font-size:13px}td,th{text-align:left;border-bottom:1px solid #d9e2e8;padding:6px}@media(max-width:900px){.grid{grid-template-columns:1fr}} </style>
<header><h1>停车场 · 可追溯分层认知地图</h1><div class="meta" id="subtitle"></div></header><main><div class="metrics" id="metrics"></div><div class="card warn" id="gaps"></div><div class="grid"><section><div class="card"><h2>空间图与观测支持</h2><div id="controls"></div><p class="legend">灰点：实测点云　蓝：帧　橙：物体　紫：已确认连接　绿：柱标区域锚点。未知空间保持灰底。</p><svg id="map" viewBox="0 0 900 600"></svg></div><div class="card"><h2>层级关系</h2><p>点击任意节点查看证据；候选归属与已核验连接分别标注。</p><svg id="hierarchy" viewBox="0 0 900 300"></svg></div></section><aside><div class="card"><h2>节点与邻接查询</h2><input id="search" placeholder="物体 ID、类别或柱子标识"><select id="select"></select><pre id="detail"></pre></div><div class="card"><h2>原始观测与检测证据</h2><select id="frameSelect"></select><img id="image"><pre id="frameDetail"></pre></div></aside></div><div class="card"><h2>实际存储文件</h2><table id="files"></table><p>运行地图采用 SQLite 保存节点、属性及邻接关系；审阅图像位于 audit。</p></div></main><script>const DATA=__DATA__;
const $=s=>document.getElementById(s),NS='http://www.w3.org/2000/svg',colors={frame:'#2788cc',object:'#db8b28',portal:'#9363be',region:'#279478',floor:'#415f77',scene:'#183448'};
function el(tag,attrs,parent){let e=document.createElementNS(NS,tag);for(let[k,v]of Object.entries(attrs))e.setAttribute(k,v);parent.appendChild(e);return e}function txt(s){return document.createTextNode(s)}
$('subtitle').textContent=DATA.config.scene+' | '+DATA.config.calibration;let r=DATA.report;
for(let[k,v]of Object.entries({'物体':r.summary.objects,'区域候选':r.summary.regions,'已确认连接':r.summary.portals,'存储降低':r.reduction_percent.toFixed(2)+'%'})){let d=document.createElement('div');d.className='card';d.append(txt(k));let b=document.createElement('div');b.className='big';b.textContent=v;d.append(b);$('metrics').append(d)}$('gaps').remove();
const kinds=['frame','object','portal','region'];for(let k of kinds){let l=document.createElement('label'),i=document.createElement('input');i.type='checkbox';i.checked=true;i.dataset.kind=k;i.onchange=draw;l.append(i,txt(k));$('controls').append(l)}
const allpos=DATA.points;const xs=allpos.map(p=>p[0]),ys=allpos.map(p=>p[1]);const xmin=Math.min(...xs),xmax=Math.max(...xs),ymin=Math.min(...ys),ymax=Math.max(...ys);const metreScale=Math.max((xmax-xmin)/840,(ymax-ymin)/540,.01);function pos(p){return[(900-(xmax-xmin)/metreScale)/2+(p[0]-xmin)/metreScale,(600-(ymax-ymin)/metreScale)/2+(ymax-p[1])/metreScale]}function nodepos(n){if(n.position)return[n.position[0],n.position[2]];if(n.T_world_camera)return[n.T_world_camera[0][3],n.T_world_camera[2][3]];if(n.positions?.length)return[n.positions[0][0],n.positions[0][2]];return null}
function choose(id){let n=DATA.nodes.find(n=>n.id===id);$('detail').textContent=JSON.stringify({node:n,adjacency:DATA.edges.filter(e=>e.source===id||e.target===id)},null,2);$('select').value=id;let f=n?.observations?.[0]?.frame_id||n?.frame_id;if(f)showFrame(f);draw(id);drawHierarchy(id)}
function draw(selected){let svg=$('map');svg.replaceChildren();for(let p of DATA.points){let[x,y]=pos(p);el('circle',{cx:x,cy:y,r:0.65,fill:'#9aa7ad',opacity:.45},svg)}let active=[...document.querySelectorAll('[data-kind]:checked')].map(e=>e.dataset.kind);for(let n of DATA.nodes){let p=nodepos(n);if(!p||!active.includes(n.kind))continue;let[x,y]=pos(p);let e=el('circle',{cx:x,cy:y,r:n.id===selected?7:n.kind==='frame'?2:4,fill:colors[n.kind],stroke:n.id===selected?'#102c40':'none'},svg);e.onclick=()=>choose(n.id);let t=el('title',{},e);t.textContent=n.id+' '+(n.label||'');}for(let n of DATA.nodes.filter(n=>n.kind==='region'))for(let p of n.positions||[]){let[x,y]=pos([p[0],p[2]]);el('circle',{cx:x,cy:y,r:7,fill:'#fff',stroke:'#279478','stroke-width':2},svg).onclick=()=>choose(n.id);let t=el('text',{x:x+9,y:y-8,fill:'#167c60','font-size':15,'font-weight':700},svg);t.textContent=n.label}let scale=el('line',{x1:30,y1:570,x2:30+10/metreScale,y2:570,stroke:'#183448','stroke-width':3},svg);let sl=el('text',{x:30,y:558,fill:'#183448','font-size':12},svg);sl.textContent='10 m';let t=el('text',{x:30,y:595,fill:'#456'},svg);t.textContent='Scene X / Z（米）；点选节点查看全部观测和邻接';}
function options(){let q=$('search').value.toLowerCase();$('select').replaceChildren();for(let n of DATA.nodes.filter(n=>JSON.stringify(n).toLowerCase().includes(q))){let o=document.createElement('option');o.value=n.id;o.textContent=n.id+' · '+(n.label||n.kind);$('select').append(o)}}$('search').oninput=options;$('select').onchange=()=>choose($('select').value);options();
function drawHierarchy(selected){let h=$('hierarchy');h.replaceChildren();const levels=['region','portal','object','frame'];let focus=new Set([selected]);for(let e of DATA.edges)if(e.source===selected||e.target===selected){focus.add(e.source);focus.add(e.target)}let positions={};let shown=[];for(let[j,k]of levels.entries()){let all=DATA.nodes.filter(n=>n.kind===k),list=all.filter(n=>focus.has(n.id));for(let n of all)if(list.length<12&&!list.includes(n))list.push(n);list=list.slice(0,12);let t=el('text',{x:20+j*220,y:22,fill:colors[k],'font-size':13},h);t.textContent=k+' '+list.length+'/'+all.length;for(let[i,n]of list.entries()){positions[n.id]=[35+j*220,43+i*20];shown.push(n)}}for(let e of DATA.edges){let a=positions[e.source],b=positions[e.target];if(!a||!b)continue;let line=el('line',{x1:a[0],y1:a[1],x2:b[0],y2:b[1],stroke:e.source===selected||e.target===selected?'#457990':'#d6e0e6','stroke-width':e.source===selected||e.target===selected?1.7:.7,'stroke-dasharray':e.kind.includes('candidate')?'3 3':'none'},h);let t=el('title',{},line);t.textContent=e.kind}for(let n of shown){let[x,y]=positions[n.id];let e=el('circle',{cx:x,cy:y,r:n.id===selected?7:4,fill:colors[n.kind]},h);e.onclick=()=>choose(n.id);let t=el('text',{x:x+8,y:y+4,'font-size':9,fill:'#183448'},h);t.textContent=(n.kind==='portal'?'门 '+n.id.split(':').slice(-2).join(':'):n.kind==='object'?(n.label||'object')+' '+n.id.split(':').slice(-2).join(':'):(n.label||n.id));t.onclick=()=>choose(n.id)}let t=el('text',{x:20,y:295,'font-size':11,fill:'#456'},h);t.textContent='展示每层最多 12 个节点，优先选中节点的邻居；虚线表示候选关系，完整关系见查询。'}
for(let f of DATA.frames){let o=document.createElement('option');o.value=f.frame_id;o.textContent=f.frame_id+' · '+f.detections.length+' detections';$('frameSelect').append(o)}function showFrame(id){let f=DATA.frames.find(f=>f.frame_id===id);if(!f)return;$('frameSelect').value=id;$('image').src='audit/images/'+id+'.jpg';$('image').onerror=()=>{$('image').removeAttribute('src')};$('frameDetail').textContent=JSON.stringify(f,null,2)}$('frameSelect').onchange=()=>showFrame($('frameSelect').value);
let tr=document.createElement('tr');for(let x of ['侧','文件','字节数']){let th=document.createElement('th');th.textContent=x;tr.append(th)}$('files').append(tr);for(let[side,fs]of [['点云',r.baseline],['认知图',r.cognitive]])for(let f of fs){let tr=document.createElement('tr');for(let x of [side,f.path,f.bytes]){let td=document.createElement('td');td.textContent=x;tr.append(td)}$('files').append(tr)}draw();if(DATA.frames.length)showFrame(DATA.frames[0].frame_id);if(DATA.nodes.length)choose(DATA.nodes.find(n=>n.kind==='object')?.id||DATA.nodes[0].id);
</script></html>'''
 (out/'index.html').write_text(page.replace('__DATA__',json.dumps(data,ensure_ascii=False).replace('<','\\u003c')))
 # Static preview is inspectable without running browser JavaScript.
 lo=points[:,[0,2]].min(0);hi=points[:,[0,2]].max(0);span=np.maximum(hi-lo,1);scale=max(span[0]/840,span[1]/540)
 def xy(p):return tuple(np.rint([(900-span[0]/scale)/2+(p[0]-lo[0])/scale,(580-span[1]/scale)/2+(hi[1]-p[1])/scale]).astype(int))
 im=Image.new('RGB',(900,620),'#edf0f3');d=ImageDraw.Draw(im)
 for p in points[:,[0,2]]:d.point(xy(p),fill='#a8b1b7')
 for n in nodes:
  p=n.get('position')
  if p is not None:
   x,y=xy([p[0],p[2]]);d.ellipse((x-3,y-3,x+3,y+3),fill='#d4842c')
 d.text((20,590),f'{c["scene"]} | points = measured support, NOT free space',fill='#163348');im.save(out/'preview.png')
